#!/usr/bin/env node
// js/*.js ES module들을 import/export 없는 단일 클래식 스크립트(app.bundle.js)로 합친다.
// file:// 로 index.html 을 직접 열 때(모듈 로딩이 차단되는 환경) 사용한다.
// GitHub Pages(https)·localhost(http) 에서는 이 번들이 아니라 js/main.js 모듈이 그대로 동작한다.
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const jsDir = path.join(root, "js");
const outPath = path.join(root, "app.bundle.js");

// 의존성/초기화 순서: 상수 → 상태 → 순수 로직 → DOM 의존 → 진입점
const order = [
  "constants.js",
  "state.js",
  "markdown.js",
  "data.js",
  "graph.js",
  "ui.js",
  "deeplink.js",
  "main.js",
];

function stripModuleSyntax(src) {
  return src
    // import { ... } from "..."; / import "..."; (멀티라인 포함)
    .replace(/^\s*import\s+[\s\S]*?from\s*["'][^"']+["'];?\s*$/gm, "")
    .replace(/^\s*import\s+["'][^"']+["'];?\s*$/gm, "")
    // export 키워드만 제거 (선언은 유지)
    .replace(/^(\s*)export\s+/gm, "$1")
    .trim();
}

const parts = order.map((file) => {
  const src = fs.readFileSync(path.join(jsDir, file), "utf8");
  return `// ---- js/${file} ----\n${stripModuleSyntax(src)}\n`;
});

const output =
  `// Generated by scripts/build-app-bundle.js — file:// 직접 열기용 클래식 번들\n` +
  `// 편집은 js/*.js 에서 하고, 이 파일은 \`node scripts/build-app-bundle.js\` 로 갱신하세요.\n` +
  `(function () {\n"use strict";\n\n${parts.join("\n")}\n})();\n`;

fs.writeFileSync(outPath, output);
console.log(`Built ${outPath} (${order.length} modules)`);
